  rt::Promise<rt::Response> rejectOnAbort(rt::AbortSignal signal, std::function<void()> onAbort) { return rt::newPromise<rt::Response>([signal,onAbort](const auto&,const rt::Reject& reject){ rt::EventListener listener=[signal,onAbort,reject](){if(onAbort)onAbort();reject(abortReason(signal));};if(signal.aborted()){if(onAbort)onAbort();reject(abortReason(signal));}else signal.addEventListener("abort",listener,{.once=true}); }); }
